"""
Combine the direct-RPA excitation amplitudes with the

bare Coulomb integrals to form the GW effective integral between every

pair of active spin-orbitals and every excitation. This quantity is the

basic coupling unit from which every later step is built.

In GW-based theories, the coupling between an

orbital pair (p, q) and a collective excitation nu is not the bare

Coulomb integral itself. It is a specific contraction of the bare

integrals against the forward (X) and backward (Y) amplitudes of the

excitation. This GW effective integral is a standard and well-established

quantity in this field, and it is not part of this paper's own new

content. The new contributions of the paper all use it as a building

block.

Returns
-------
a value M such that M[p][q][nu] is the GW     effective integral between active spin-orbitals p and q for     excitation nu. This holds for every p, q in 0..n-1, where n is the     number of active spin-orbitals, and for every nu in 0..len(omega)-1.
"""

# =============================================================================
# FUNCTION SIGNATURE (shown to the LLM)
# =============================================================================

def gw_effective_integrals(
    eps: list[float],
    chem_spatial: dict[tuple[int, int, int, int], float],
    occ: list[int],
    vir: list[int],
    omega: list[float],
    X: list[list[float]],
    Y: list[list[float]],
) -> list[list[list[float]]]:
    """
    Compute the GW effective integral for every active spin-orbital
    pair and every excitation.

    Args:
        eps: orbital energy of each active spin-orbital.
        chem_spatial: two-electron Coulomb integrals over the active
            spatial orbitals, as in the direct-RPA step. A key that is
            absent has value 0.0. The spin-orbital physicist-notation
            integral <pq|rs> equals chem_spatial[(p//2, r//2, q//2,
            s//2)] if p, r have the same spin and q, s have the same
            spin. In all other cases it is 0.0.
        occ, vir: the occupied and virtual active spin-orbital indices.
        omega: excitation energies, in the same order as X and Y.
        X, Y: forward and backward amplitudes for each excitation nu.
            Each X[nu] (and each Y[nu]) is a list over the
            occupied-virtual pairs. The pairs are built by pairing every
            occupied spin-orbital with every same-spin virtual
            spin-orbital, occ[0] first, in the order occ and vir are
            given.

    """
    return []

# =============================================================================
# GOLD SOLUTION
# =============================================================================

def _oracle_gw_effective_integrals(
    eps: list[float],
    chem_spatial: dict[tuple[int, int, int, int], float],
    occ: list[int],
    vir: list[int],
    omega: list[float],
    X: list[list[float]],
    Y: list[list[float]],
) -> list[list[list[float]]]:
    ov = [(i, a) for i in occ for a in vir if i % 2 == a % 2]
    n = len(eps)
    nexc = len(omega)

    def _phys(p, q, r, s):
        if p % 2 != r % 2 or q % 2 != s % 2:
            return 0.0
        return chem_spatial.get((p//2, r//2, q//2, s//2), 0.0)

    M = [[[0.0]*nexc for _ in range(n)] for _ in range(n)]
    for nu in range(nexc):
        for p in range(n):
            for q in range(n):
                M[p][q][nu] = sum(
                    _phys(p, a, q, i)*X[nu][I] + _phys(p, i, q, a)*Y[nu][I]
                    for I, (i, a) in enumerate(ov)
                )
    return M

